export const defaults={film:'Original',amount:100,lutAmount:100,dr:100,grain:0,wb:'Auto',red:0,blue:0,highlight:0,shadow:0,color:0,sharpness:0,nr:-4,exposure:0,temperature:0};
export const films={'Original':[1,1,0,0,0],'Classic Chrome':[.77,1.12,3,0,-3],'Classic Neg.':[.85,1.22,5,-3,-5],'PROVIA':[1.05,1.05,0,0,0],'Velvia':[1.4,1.15,2,0,-2],'ASTIA':[.95,.91,4,0,1],'ETERNA':[.7,.82,1,2,4],'ACROS':[0,1.17,0,0,0],'Nostalgic Neg.':[.87,.96,9,3,-5]};
export function parseCube(text){let size=0,rows=[],min=[0,0,0],max=[1,1,1],title='Custom LUT';for(let line of text.split(/\r?\n/)){line=line.replace(/#.*/,'').trim();if(!line)continue;const p=line.split(/\s+/);if(p[0]==='TITLE'){title=line.slice(5).trim().replace(/^"|"$/g,'');continue}if(p[0]==='LUT_1D_SIZE')throw Error('Chỉ hỗ trợ LUT 3D .cube, chưa hỗ trợ LUT 1D.');if(p[0]==='LUT_3D_SIZE'){size=Number(p[1]);continue}if(p[0]==='DOMAIN_MIN'){min=p.slice(1).map(Number);continue}if(p[0]==='DOMAIN_MAX'){max=p.slice(1).map(Number);continue}if(p.length!==3||p.some(v=>!Number.isFinite(Number(v))))throw Error('Dòng LUT không hợp lệ: '+line.slice(0,60));rows.push(...p.map(Number))}if(!Number.isInteger(size)||size<2||size>65)throw Error('LUT cần kích thước từ 2 đến 65.');if(rows.length!==size**3*3)throw Error('Số điểm màu trong LUT không khớp kích thước.');if(min.length!==3||max.length!==3||min.some((x,i)=>!Number.isFinite(x)||!Number.isFinite(max[i])||max[i]<=x))throw Error('Miền màu LUT không hợp lệ.');return {size,data:new Float32Array(rows),min,max,title}}
const clamp=(v,lo=0,hi=255)=>Math.max(lo,Math.min(hi,v));
export function sampleLut(lut,r,g,b){const v=[r,g,b].map((x,i)=>clamp((x/255-lut.min[i])/(lut.max[i]-lut.min[i]),0,1)*(lut.size-1));const low=v.map(Math.floor),f=v.map((x,i)=>x-low[i]);let out=[0,0,0];for(let z=0;z<2;z++)for(let y=0;y<2;y++)for(let x=0;x<2;x++){const idx=(Math.min(low[0]+x,lut.size-1)+Math.min(low[1]+y,lut.size-1)*lut.size+Math.min(low[2]+z,lut.size-1)*lut.size**2)*3;const w=(x?f[0]:1-f[0])*(y?f[1]:1-f[1])*(z?f[2]:1-f[2]);for(let c=0;c<3;c++)out[c]+=lut.data[idx+c]*255*w}return out}
export function processPixels(input,width,height,s,lut){const out=new Uint8ClampedArray(input.length),film=films[s.film]||films.Original;const exp=2**s.exposure,wb={Auto:0,Daylight:3,Cloudy:9,Tungsten:-15}[s.wb]||0;for(let i=0;i<input.length;i+=4){let a=[input[i],input[i+1],input[i+2]];a[0]+=s.red*2+s.temperature*.15+wb;a[2]+=s.blue*2-s.temperature*.15-wb;const l=a[0]*.2126+a[1]*.7152+a[2]*.0722;let v=a.map((c,k)=>{let filmc=(l+(c-l)*film[0]-128)*film[1]+128+film[k+2];let value=c+(filmc-c)*s.amount/100;value*=exp;const lum=clamp(value/255,0,1);value+=s.highlight*10*lum**2-s.shadow*10*(1-lum)**2;value-=((s.dr-100)/300)*28*lum**3;return value});const lum=v[0]*.2126+v[1]*.7152+v[2]*.0722;v=v.map(c=>lum+(c-lum)*(1+s.color*.09));if(lut){const mapped=sampleLut(lut,...v);v=v.map((c,k)=>c+(mapped[k]-c)*s.lutAmount/100)}const n=(((Math.imul(i+11,1597334677)>>>0)%1024)/1023-.5)*s.grain;for(let k=0;k<3;k++)out[i+k]=clamp(v[k]+n);out[i+3]=input[i+3]}
if(s.sharpness!==0||s.nr>-4){const source=out.slice(),denoise=Math.max(0,(s.nr+4)/8)*.65,sh=s.sharpness*.18;for(let y=1;y<height-1;y++)for(let x=1;x<width-1;x++){let p=(y*width+x)*4;for(let c=0;c<3;c++){const avg=(source[p-4+c]+source[p+4+c]+source[p-width*4+c]+source[p+width*4+c])/4;let v=source[p+c];if(s.nr>-4)v+=(avg-v)*denoise;out[p+c]=clamp(v+(v-avg)*sh)}}}return out}

